package com.example.rokidgeminisecretary;
import android.content.*;import org.json.*;import java.io.*;import java.util.*;
final class ConversationTools {
 static synchronized JSONObject templates(Context c)throws Exception{JSONObject doc=ReviewStore.read(c,"conversation-templates");if(!doc.has("items"))doc.put("items",new JSONArray());return new JSONObject(doc.toString()).put("revision",ReviewStore.hash(doc));}
 static synchronized JSONObject template(Context c,JSONObject input)throws Exception{JSONObject current=templates(c);if(!current.getString("revision").equals(input.getString("revision")))throw new IOException("定型文が更新されました。開き直してください");String id=input.getString("id"),action=input.getString("action");ReviewStore.validId(id);if(!action.matches("save|delete"))throw new IOException("操作を確認してください");JSONArray next=new JSONArray(),rows=current.getJSONArray("items");for(int i=0;i<rows.length();i++)if(!id.equals(rows.getJSONObject(i).getString("id")))next.put(rows.getJSONObject(i));if(action.equals("save")){String text=input.getString("text").trim(),title=input.getString("title").trim();if(text.isEmpty()||text.length()>2400||title.isEmpty()||title.length()>60||next.length()>=30)throw new IOException("定型文は30件、本文2400文字・名前60文字以内です");next.put(new JSONObject().put("id",id).put("title",title).put("text",text));}ReviewStore.write(c,"conversation-templates",new JSONObject().put("items",next));return templates(c);}
 static JSONArray drafts(Context c)throws Exception{JSONArray rows=ReviewStore.read(c,"conversation-drafts").optJSONArray("items"),out=new JSONArray();long now=System.currentTimeMillis();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long age=now-row.optLong("at");if(age>=0&&age<86400000L)out.put(row);}return out;}
 static String draftOwner(String token)throws Exception{if(token==null||token.length()<16)throw new IOException("接続を確認してください");return RecorderPhotoStore.hash(token.getBytes("UTF-8"));}
 static synchronized JSONObject draft(Context c,String token)throws Exception{String owner=draftOwner(token);JSONArray rows=drafts(c);for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(owner.equals(row.getString("owner")))return new JSONObject().put("text",row.getString("text")).put("at",row.getLong("at")).put("revision",row.getString("revision"));}return new JSONObject().put("text","").put("revision","");}
 static synchronized JSONObject draft(Context c,String token,JSONObject input)throws Exception{String owner=draftOwner(token),text=input.getString("text");if(text.length()>2400)throw new IOException("下書きは2400文字以内です");JSONObject old=draft(c,token);if(!old.getString("revision").equals(input.getString("revision")))throw new IOException("別の画面で下書きが変わりました。保存を止めて開き直してください");JSONArray rows=drafts(c),next=new JSONArray();for(int i=0;i<rows.length();i++)if(!owner.equals(rows.getJSONObject(i).getString("owner")))next.put(rows.getJSONObject(i));if(!text.trim().isEmpty()){if(next.length()>=8)throw new IOException("下書きの保存上限です");long at=System.currentTimeMillis();next.put(new JSONObject().put("owner",owner).put("text",text).put("at",at).put("revision",RecorderPhotoStore.hash((at+":"+text).getBytes("UTF-8"))));}ReviewStore.write(c,"conversation-drafts",new JSONObject().put("items",next));return draft(c,token);}
 static synchronized void clearDraft(Context c,String token)throws Exception{JSONObject old=draft(c,token);draft(c,token,new JSONObject().put("revision",old.getString("revision")).put("text",""));}
 static JSONObject search(JSONArray history,JSONArray ledger,String text,String from,String until,String images)throws Exception{if(text.length()>100||!images.matches("any|with|without"))throw new IOException("検索条件を確認してください");java.time.ZoneId zone=java.time.ZoneId.of("Asia/Tokyo");long start=from.isEmpty()?0:java.time.LocalDate.parse(from).atStartOfDay(zone).toInstant().toEpochMilli(),end=until.isEmpty()?Long.MAX_VALUE:java.time.LocalDate.parse(until).plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli();if(end<=start)throw new IOException("日付の範囲を確認してください");HashSet<String> imageKeys=new HashSet<>();for(int i=0;i<ledger.length();i++){JSONObject row=ledger.getJSONObject(i);if(!row.optString("referenceKey").isEmpty())imageKeys.add(row.optString("key"));}JSONArray groups=ConversationCollections.group(history),found=new JSONArray();for(int i=0;i<groups.length();i++){JSONObject card=groups.getJSONObject(i);JSONArray rows=card.getJSONArray("rows");boolean image=imageKeys.contains(card.getString("key")),match=text.isEmpty(),date=false;for(int j=0;j<rows.length();j++){JSONObject row=rows.getJSONObject(j);image|=row.optString("kind").contains("画像");match|=row.optString("message").toLowerCase(Locale.ROOT).contains(text.toLowerCase(Locale.ROOT));date|=row.optLong("time")>=start&&row.optLong("time")<end;}if(match&&date&&(images.equals("any")||images.equals("with")==image))found.put(new JSONObject(card.toString()).put("imageRecorded",image));}return new JSONObject().put("items",found).put("scope","現在の共有履歴の保持範囲。日付は日本時間。画像の記録がない旧会話は画像なしとは断定できません。");}
 static void topicQueued(Context c,String id,long expires)throws Exception{if(!c.getSharedPreferences("conversation-topic-gate",0).edit().putString("id",id).putLong("expires",expires).commit())throw new IOException("話題の切替状態を保存できません");}
 static void topicReady(Context c)throws Exception{SharedPreferences prefs=c.getSharedPreferences("conversation-topic-gate",0);String id=prefs.getString("id","");if(id.isEmpty())return;JSONObject state=ConversationWorkspace.snapshot(c);if(id.equals(state.optString("commandId"))&&state.optString("commandPhase").matches("COMPLETED|FAILED")){prefs.edit().clear().commit();if(state.optString("commandPhase").equals("FAILED"))throw new IOException("話題の切替は失敗しました。前の文脈のままです。状態を確認してください");return;}if(System.currentTimeMillis()>prefs.getLong("expires",0)){prefs.edit().clear().commit();throw new IOException("話題切替の結果が未確認です。状態を確認してから送信してください");}throw new IOException("話題切替をメガネで確認中です。確認後に送信してください");}
 static void requireNoPending(Context c)throws Exception{JSONArray all=ConversationContinuation.ledger(c);for(int i=0;i<all.length();i++)if(all.getJSONObject(i).optBoolean("tracked")&&!TrackedWebRequest.terminal(all.getJSONObject(i).optString("requestState")))throw new IOException("未完了の依頼を確認してから話題を切り替えてください");}
 private ConversationTools(){}
}
